from pathlib import Path
R=Path(__file__).parent;C=R.parent/'halo-field'
def add(el,s):
 p=C/'elements'/el/'element.css';root=('[data-el="halo-field-'+el+'"]')*3;p.write_text(p.read_text()+'\n'+s.replace('$',root))
add('chart-line','''$>.pt{position:static} $>.pt>b{position:relative;bottom:auto;transform:translateY(-100%);anchor-name:var(--halo-field-point)} $>.pt>b:after{content:'';position:absolute;left:calc(50% - 5px);top:calc(100% + 2px);width:10px;height:10px;border-radius:50%;border:2px solid var(--a1);background:var(--page)} $>.pt:before,$>.pt:after{content:'';position:absolute;left:anchor(var(--halo-field-prev) center);right:anchor(var(--halo-field-point) center);width:auto;height:auto;border:0;border-radius:0;z-index:0} $>.pt:before{top:anchor(var(--halo-field-prev) bottom);bottom:anchor(var(--halo-field-point) bottom);clip-path:none;background:linear-gradient(to top right,transparent calc(50% - 1px),var(--a1) 50%,transparent calc(50% + 1px))} $>.pt:after{top:anchor(var(--halo-field-point) bottom);bottom:anchor(var(--halo-field-prev) bottom);background:linear-gradient(to bottom right,transparent calc(50% - 1px),var(--a1) 50%,transparent calc(50% + 1px))} $>.pt:first-child:before,$>.pt:first-child:after{content:none} $>.pt>span{top:auto;bottom:0}''')
add('chart-area','''$>.series{--halo-field-h:calc(100cqh - var(--gap-lg)*2)} $ .pt{margin-top:calc((1 - var(--v)/var(--max))*var(--halo-field-h))} $ .pt:before{top:calc(anchor(var(--halo-field-prev) top) - var(--halo-field-h));clip-path:polygon(0 var(--halo-field-h),100% calc(100% - var(--v)/var(--max)*var(--halo-field-h)),100% 100%,0 100%)}''')
# valid plain source code uses the permitted coding font from the kit's declared body family? code needs monospaced, therefore code override via allowed typeface declaration extension would violate shared font only; keep toolkit body.
# tighten full program layout without non-contract children
p=R/'build_review.py';s=p.read_text();start=s.index("D[12]=E('callout'");end=s.index('\nrows=',start)
s=s[:start]+'''D[12]=E('callout','callout','<p>온라인 매출 전년 대비 <b>150% 증대</b> 및 브랜드 인지도 강화</p>',pos(row=1,h=1))+group([E('headline','headline',f'<p class="kick">0{i+1}</p><h2>{n}</h2>') for i,n in enumerate(['검색 광고','디스플레이','숏폼 콘텐츠','체험단 운영'])],pos(row=2,h=1))+group([E('image-frame','frame',f'<div class="seat" data-ph="{i+1}"></div>') for i in range(4)],pos(row=3,h=4))''' +s[end:];p.write_text(s)
